const pg = global.get('pg');
const bcrypt = global.get('bcrypt');
const jwt = global.get('jwt');
const dbConfig = global.get('dbConfig');
const jwtSecret = global.get('jwtSecret');

if (!pg || !bcrypt || !jwt || !dbConfig || !jwtSecret) {
    msg.statusCode = 500;
    msg.payload = { error: 'Error de configuración del servidor: faltan dependencias.' };
    return msg;
}

const client = new pg.Client({ ...dbConfig, connectionTimeoutMillis: 5000 });

try {
    const { email, password, full_name, phone } = msg.payload;
    if (!email || !password) {
        msg.statusCode = 400;
        msg.payload = { error: 'Email y password son requeridos' };
        return msg;
    }
    if (password.length < 8) {
        msg.statusCode = 400;
        msg.payload = { error: 'Password debe tener al menos 8 caracteres' };
        return msg;
    }
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
        msg.statusCode = 400;
        msg.payload = { error: 'Email invalido' };
        return msg;
    }

    await client.connect();
    const existing = await client.query('SELECT id FROM users WHERE email = $1', [email.toLowerCase()]);
    if (existing.rows.length > 0) {
        msg.statusCode = 409;
        msg.payload = { error: 'El email ya esta registrado' };
        return msg;
    }

    const password_hash = await bcrypt.hash(password, 10);
    const userResult = await client.query(
        'INSERT INTO users (email, password_hash, full_name, phone, role, is_active) VALUES ($1, $2, $3, $4, $5, true) RETURNING id, email, full_name, role',
        [email.toLowerCase(), password_hash, full_name || null, phone || null, 'customer']
    );
    const user = userResult.rows[0];

    const tenantResult = await client.query(
        'INSERT INTO tenants (name, owner_user_id, is_active) VALUES ($1, $2, true) RETURNING id',
        [email.split('@')[0], user.id]
    );

    msg.statusCode = 201;
    msg.payload = { success: true, user: user, tenant_id: tenantResult.rows[0].id };
    return msg;

} catch (err) {
    node.error('Register error: ' + err.message, msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Error interno del servidor' };
    return msg;
} finally {
    await client.end().catch(() => {});
}

const pg = global.get('pg');
const bcrypt = global.get('bcrypt');
const jwt = global.get('jwt');
const dbConfig = global.get('dbConfig');
const jwtSecret = global.get('jwtSecret');

if (!pg || !bcrypt || !jwt || !dbConfig || !jwtSecret) {
    msg.statusCode = 500;
    msg.payload = { error: 'Error de configuración del servidor: faltan dependencias o variables globales.' };
    return msg;
}

const client = new pg.Client({ ...dbConfig, connectionTimeoutMillis: 5000 });

try {
    const { email, password } = msg.payload;
    if (!email || !password) {
        msg.statusCode = 400;
        msg.payload = { error: 'Email y password son requeridos' };
        return msg;
    }

    await client.connect();

    const result = await client.query(
        'SELECT u.id, u.email, u.password_hash, u.full_name, u.phone, u.role, u.is_active, t.id as tenant_id FROM users u LEFT JOIN tenants t ON t.owner_user_id = u.id AND t.is_active = true WHERE u.email = $1',
        [email.toLowerCase()]
    );

    if (result.rows.length === 0) {
        msg.statusCode = 401;
        msg.payload = { error: 'Credenciales invalidas' };
        return msg;
    }

    const user = result.rows[0];
    if (!user.is_active) {
        msg.statusCode = 403;
        msg.payload = { error: 'Cuenta desactivada' };
        return msg;
    }

    const match = await bcrypt.compare(password, user.password_hash);
    if (!match) {
        msg.statusCode = 401;
        msg.payload = { error: 'Credenciales invalidas' };
        return msg;
    }

    const token = jwt.sign(
        { user_id: user.id, email: user.email, role: user.role, tenant_id: user.tenant_id },
        jwtSecret,
        { expiresIn: '24h' }
    );

    msg.statusCode = 200;
    msg.payload = {
        success: true,
        token: token,
        user: {
            id: user.id,
            email: user.email,
            full_name: user.full_name,
            role: user.role,
            tenant_id: user.tenant_id
        }
    };
    return msg;

} catch (err) {
    node.error('Login error: ' + err.message, msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Error interno del servidor al procesar el login' };
    return msg;
} finally {
    await client.end().catch(() => {});
}

const pg = global.get('pg');
const jwt = global.get('jwt');
const dbConfig = global.get('dbConfig');
const jwtSecret = global.get('jwtSecret');
const client = new pg.Client(dbConfig);
try {
    const authHeader = msg.req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        msg.statusCode = 401;
        msg.payload = { error: 'Token no proporcionado' };
        return msg;
    }
    const token = authHeader.substring(7);
    let decoded;
    try {
        decoded = jwt.verify(token, jwtSecret);
    } catch (e) {
        msg.statusCode = 401;
        msg.payload = { error: 'Token invalido o expirado' };
        return msg;
    }
    await client.connect();
    const result = await client.query('SELECT u.id, u.email, u.full_name, u.phone, u.role, u.is_active, u.created_at, t.id as tenant_id, t.name as tenant_name FROM users u LEFT JOIN tenants t ON t.owner_user_id = u.id WHERE u.id = $1', [decoded.user_id]);
    if (result.rows.length === 0) {
        msg.statusCode = 404;
        msg.payload = { error: 'Usuario no encontrado' };
        return msg;
    }
    msg.statusCode = 200;
    msg.payload = { success: true, user: result.rows[0] };
    return msg;
} catch (err) {
    node.error('Profile: ' + err.message, msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Error interno del servidor' };
    return msg;
} finally {
    client.end().catch(() => {});
}

let data = msg.payload;

if (typeof data === 'string') {
    try { data = JSON.parse(data); }
    catch (e) { node.error('JSON inválido'); return null; }
}

const mac = data.mac || 'unknown';
const name = data.node_name || data.name || mac;
const event = (data.event || 'UNKNOWN').toUpperCase();
const seq = data.seq || 0;
const battery = data.battery || 0;
const tenant = data.tenant || '0';
const site = data.site || 'site0';
const location = data.location || '';
const room = data.room || '';

const measurement = 'node_events';
const tags = `device_id="${mac}",name="${name}",tenant="${tenant}",site="${site}",event_type="${event}"`;
const fields = `seq=${seq}i,battery=${battery}i`;
const timestamp = Date.now() * 1000000;

let msgInflux = {
    payload: `${measurement},${tags} ${fields} ${timestamp}`,
    topic: 'influx_write',
    normalized: { mac, name, event, seq, battery, tenant, site, location, room }
};

let msgGotify = {
    normalized: { mac, name, event, seq, battery, tenant, site, location, room },
    is_alarm: ['ALRM', 'GAS', 'SMOKE', 'FIRE', 'PANIC', 'MOV', 'DOOR', 'SEIS', 'SOS', 'HUM'].some(prefix => event.startsWith(prefix))
};

return [msgInflux, msgGotify];

if (!msg.is_alarm) {
    return null;
}

const d = msg.normalized;
const devName = d.name || d.mac || 'Desconocido';
const ubicacion = d.location ? `${d.location} - ${d.room}` : d.site;

let title = '🚨 Alarma Seguimiento 360';
let message = `Evento: ${d.event}\nDispositivo: ${devName}\nUbicación: ${ubicacion}\nBatería: ${d.battery}%`;
let priority = 5;

if (d.event === 'GAS') {
    title = '⚠️ FUGA DE GAS DETECTADA';
    message = `Sensor: ${devName}\nUbicación: ${ubicacion}\n¡EVACUAR INMEDIATAMENTE!`;
    priority = 10;
} else if (d.event === 'SMOKE' || d.event === 'FIRE') {
    title = '🔥 HUMO/FOGO DETECTADO';
    message = `Sensor: ${devName}\nUbicación: ${ubicacion}`;
    priority = 10;
} else if (d.event === 'PANIC' || d.event === 'SOS') {
    title = '🆘 BOTÓN DE PÁNICO';
    message = `Dispositivo: ${devName}\nUbicación: ${ubicacion}`;
    priority = 10;
}

msg.payload = {
    title: title,
    message: message,
    priority: priority
};

node.log(`✅ Enviando alerta a Gotify: ${title} (${devName})`);
return msg;

const payload = msg.payload;

if (!payload || !payload.mac) {
    node.warn('Mensaje HUB_ONLINE sin MAC');
    return null;
}

const mac = payload.mac.replace(/:/g, '').toLowerCase();
// OJO: si el hub no manda su nombre, se envia null (no un texto por
// defecto). El UPDATE usa COALESCE($2, name), asi que null conserva el
// nombre que ya tiene en la base. Mandar 'Hub Sin Nombre' lo borraba.
const hubName = payload.hub_name || null;
const event = payload.event || 'HUB_ONLINE';

/* El mismo topic lleva el alta y la LWT de caida. Sin distinguirlos, el
 * HUB_OFFLINE retained del broker ponía 'active' en cada arranque de
 * Node-RED y el hub muerto parecia recién visto. */
const estado = (event === 'HUB_OFFLINE') ? 'offline' : 'active';

msg.params = [mac, hubName, estado];
msg.hubData = { mac, hubName, event, estado };

node.log((estado === 'active' ? (event === 'HUB_HEARTBEAT' ? 'Latido del hub: ' : 'Hub conectado: ') : 'Hub reportado OFFLINE: ')
         + mac + ' (' + (hubName || 'conserva nombre en BD') + ')');
return msg;

/* Los latidos de estado no van a la auditoria: serian 288 filas por dia
 * por hub y no describen ninguna accion de nadie. */
if (msg.hubData && msg.hubData.event === 'HUB_HEARTBEAT') return null;
const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;

if (!row) {
    node.warn(`Hub no encontrado en BD para MAC: ${msg.hubData.mac}. ¿Falta registrar el Hub?`);
    return null;
}

// CRÍTICO: Usar msg.params (no msg.auditParams) para que el nodo PostgreSQL lo reconozca
msg.params = [
    null,                              // $1: device_id (NULL para hubs)
    row.tenant_id,                     // $2: tenant_id
    null,                              // $3: performed_by (sistema)
    (msg.hubData.event === 'HUB_OFFLINE' ? 'hub_offline' : 'hub_online'),  // $4
    JSON.stringify({                   // $5: details (JSONB)
        mac: msg.hubData.mac,
        hub_name: msg.hubData.hubName,
        hub_id: row.id,
        event: msg.hubData.event
    })
];

msg.hubRow = row;
return msg;

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    return [msg, null];
} catch(e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token inválido o expirado' };
    return [null, msg];
}

const hubId = parseInt(msg.req.query.hub_id, 10);
if (!hubId) {
    msg.statusCode = 400;
    msg.payload = { error: 'Parámetro hub_id requerido' };
    return [null, msg];
}
msg.params = [msg._user.tenant_id, hubId];
return [msg, null];

msg.statusCode = 200;
msg.payload = msg.payload || [];
return msg;

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    return [msg, null];
} catch(e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token inválido o expirado' };
    return [null, msg];
}

const b = msg.payload || {};
const hubId = parseInt(b.hub_id, 10);
const macAddress = (b.mac_address || '').trim().toLowerCase();
const name = (b.name || 'Nodo Sin Nombre').trim();
const location = (b.location || 'Sin Ubicación').trim();
const room = (b.room || 'Sin Habitación').trim();
const threshold = parseInt(b.distance_threshold, 10) || 50;

if (!hubId || !macAddress) {
    msg.statusCode = 400;
    msg.payload = { error: 'hub_id y mac_address son requeridos' };
    return [null, msg];
}

if (!/^([0-9a-f]{2}:){5}[0-9a-f]{2}$/.test(macAddress)) {
    msg.statusCode = 400;
    msg.payload = { error: 'mac_address debe tener formato xx:xx:xx:xx:xx:xx' };
    return [null, msg];
}

if (threshold < 2 || threshold > 200) {
    msg.statusCode = 400;
    msg.payload = { error: 'distance_threshold debe estar entre 2 y 200 cm' };
    return [null, msg];
}

msg.params = [hubId, macAddress, name, location, room, threshold, msg._user.tenant_id];
return [msg, null];

const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
if (!row) {
    msg.statusCode = 403;
    msg.payload = { error: 'Hub no encontrado o sin permisos' };
    return msg;
}
msg.statusCode = 201;
msg.payload = { success: true, node: row };
return msg;

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    return [msg, null];
} catch(e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token inválido o expirado' };
    return [null, msg];
}

const nodeId = parseInt(msg.req.params.id, 10);
const b = msg.payload || {};

const name = (b.name || '').trim();
const location = (b.location || '').trim();
const room = (b.room || '').trim();
const threshold = parseInt(b.distance_threshold, 10);

if (!nodeId || (!name && !location && !room && isNaN(threshold))) {
    msg.statusCode = 400;
    msg.payload = { error: 'Debe enviar al menos name, location, room o distance_threshold' };
    return [null, msg];
}

if (!isNaN(threshold) && (threshold < 2 || threshold > 200)) {
    msg.statusCode = 400;
    msg.payload = { error: 'distance_threshold debe estar entre 2 y 200 cm' };
    return [null, msg];
}

msg.params = [
    name || null,
    location || null,
    room || null,
    isNaN(threshold) ? null : threshold,
    nodeId,
    msg._user.tenant_id
];

msg.nodeUpdate = { nodeId, name, location, room, threshold };
return [msg, null];

const row = Array.isArray(msg.payload) ? msg.payload[0] : null;

if (!row) {
    msg.statusCode = 404;
    msg.payload = { error: 'Nodo no encontrado o sin permisos de tenant' };
    return [null, msg];
}

const missing = [];
if (!row.tenant_id) missing.push('tenant_id');
if (!row.site_id)    missing.push('site_id');
if (!row.hub_mac)    missing.push('serial_number');

if (missing.length > 0) {
    node.error('Faltan en hubs: ' + missing.join(', '), msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Hub incompleto en BD: faltan ' + missing.join(', ') };
    return [null, msg];
}

const hubMac = String(row.hub_mac).replace(/:/g, '').toLowerCase();
const topic = 'seguimiento360/tenant/' + row.tenant_id +
              '/site/'    + row.site_id  +
              '/hub/'     + hubMac       +
              '/node_cfg';

if (topic.includes('undefined') || topic.includes('null')) {
    node.error('Topic invalido: ' + topic, msg);
    msg.statusCode = 500;
    msg.payload = { error: 'Topic MQTT invalido' };
    return [null, msg];
}

msg.topic = topic;
msg.payload = {
    action: 'UPDATE_NODE',
    node_mac: row.node_mac,
    node_name: row.name,
    location: row.location,
    room: row.room,
    distance_threshold: row.distance_threshold,
    issued_by: msg._user ? msg._user.user_id : 'system',
    issued_at: new Date().toISOString()
};
msg.nodeRow = row;

node.log('📤 topic=' + topic);
return [msg, null];

msg.statusCode = 200;
msg.payload = {
    success: true,
    node: msg.nodeRow,
    mqtt_topic: msg.topic,
    message: 'Nodo actualizado en BD y configuración publicada al Hub vía MQTT'
};
return msg;

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    return [msg, null];
} catch(e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token inválido o expirado' };
    return [null, msg];
}

const nodeId = parseInt(msg.req.params.id, 10);
if (!nodeId) {
    msg.statusCode = 400;
    msg.payload = { error: 'ID de nodo inválido' };
    return [null, msg];
}
msg.params = [nodeId, msg._user.tenant_id];
return [msg, null];

/* El DELETE del nodo devuelve la fila que quito. Si no devolvio nada no habia
 * permiso ni nodo, y la MAC se deja vacia a proposito: no hay que borrar ni un
 * evento por una peticion que no borro el nodo. */
const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
msg.nodeBorrado = row || null;
msg.params = [row ? String(row.mac_address || '') : ''];
return msg;

const row = msg.nodeBorrado;
if (!row) {
    msg.statusCode = 404;
    msg.payload = { error: 'Nodo no encontrado o sin permisos' };
    return msg;
}
const eventos = Array.isArray(msg.payload) ? msg.payload.length : 0;
msg.statusCode = 200;
msg.payload = {
    success: true,
    deleted: row,
    events_deleted: eventos,
    message: 'Nodo eliminado con ' + eventos + ' registros de su historial'
};
return msg;

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    return [msg, null];
} catch(e) {
    msg.statusCode = 401;
    msg.payload = { error: 'Token inválido o expirado' };
    return [null, msg];
}

const hubId = parseInt(msg.payload.hub_id, 10);
if (!hubId) {
    msg.statusCode = 400;
    msg.payload = { error: 'hub_id es requerido en el payload' };
    return [null, msg];
}
msg.params = [hubId, msg._user.tenant_id];
msg.hubId = hubId;
return [msg, null];

// 1. Obtener la fila de la base de datos
const row = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;

if (!row || !row.serial_number) {
    msg.statusCode = 404;
    msg.payload = { error: 'Hub no encontrado en la base de datos' };
    return [null, msg]; // Salida 2: Error
}

// 2. Construir el tópico MQTT (sin dos puntos en la MAC)
const hubMac = String(row.serial_number).replace(/:/g, '').toLowerCase();
const topic = `seguimiento360/tenant/${row.tenant_id}/site/${row.site_id}/hub/${hubMac}/ota_cmd`;

// 3. URL del firmware (Asegúrate que esta URL sea accesible desde el ESP32)
const firmwareUrl = "https://seguimiento360.com/ota/firmware_v1.bin";

// 4. Preparar la Respuesta HTTP (Salida 1)
msg.statusCode = 200;
msg.payload = {
    success: true,
    message: `Comando OTA enviado al Hub: ${row.name || 'Hub Sin Nombre'}`,
    topic: topic,
    firmware_url: firmwareUrl
};

// 5. Preparar el mensaje MQTT (Salida 2)
// CRÍTICO: Crear un objeto completamente nuevo para MQTT
const mqttMsg = {
    topic: topic,
    payload: firmwareUrl,
    qos: 1
};

// Enviar por ambas salidas simultáneamente
return [msg, mqttMsg];

// Este nodo solo pasa el mensaje al http response
// msg.payload y msg.statusCode ya están configurados en el nodo anterior
return msg;

const parts = msg.topic.split("/");
const tid = parseInt(parts[2], 10);
const sid = parseInt(parts[4], 10);
const hubMac = parts[6];
const d = msg.payload || {};
if (!d.event) { return null; }

// Valor del evento: clave nueva `value` (SPEC-02 v0.3) con fallback a la
// historica `distance_cm` mientras siga habiendo hubs sin reflashear.
const valor = (d.value != null ? d.value : (d.distance_cm != null ? d.distance_cm : null));

// --- Mensaje 1: INSERT event ---
msg.params = [
  tid, sid, hubMac,
  d.mac || null,
  d.node_name || d.name || null,
  String(d.event).toUpperCase(),
  (d.battery != null ? d.battery : null),
  valor,
  (d.seq != null ? d.seq : null),
  JSON.stringify(d)
];

// --- Mensaje 2: push, solo para alarmas ---
const ev = String(d.event).toUpperCase();

// Gravedad: define el titulo y el tono del aviso
const GRAVES = ["FIRE","GAS","SMOKE","PANIC","SOS","SEIS","ALRM"];
const MEDIAS = ["DOOR","MOV","HUM"];
let gravedad = "aviso";
if (GRAVES.some(p => ev.startsWith(p))) gravedad = "critica";
else if (MEDIAS.some(p => ev.startsWith(p))) gravedad = "media";

if (gravedad === "aviso") { return [msg, null]; }

// Estado legible para puertas: 1=Cerrado, 0=Abierto (SPEC-02 v0.3)
const esDoor = ev.startsWith("DOOR");
const estado = esDoor && valor != null ? (Number(valor) === 1 ? "Cerrado" : "Abierto") : null;

// El SELECT de tokens necesita el hub ($1) y el mac del nodo ($2) para
// resolver el nombre desde la base de datos (el hub no lo sabe).
const msgPush = {
  params: [hubMac, d.mac || null],
  push: {
    event: ev,
    gravedad: gravedad,
    nodo: d.node_name || d.name || d.mac || "sensor",
    habitacion: d.room || null,
    ubicacion: d.location || null,
    estado: estado,
    distancia: (esDoor ? null : (valor != null ? Number(valor) : null)),
    bateria: (d.battery != null ? Number(d.battery) : null),
    secuencia: (d.seq != null ? Number(d.seq) : null)
  },
  // Texto corto, para el registro del nodo
  alarma: "Alarma: " + (d.node_name || d.name || d.mac || "sensor")
};
node.warn("DEBUG parse: params=" + JSON.stringify(msg.params));
node.warn("DEBUG parse: push=" + JSON.stringify(msgPush));
return [msg, msgPush];

const jwt = global.get('jwt');
const jwtSecret = global.get('jwtSecret');
const auth = (msg.req.headers['authorization'] || '');
if (!auth.startsWith('Bearer ')) {
    msg.statusCode = 401;
    msg.payload = { error: 'No autorizado' };
    return [null, msg];
}
try {
    msg._user = jwt.verify(auth.slice(7), jwtSecret);
    msg.params = [msg._user.tenant_id];
    return [msg, null];
