msg.params = [nodeId, usuario.tenant_id];
return [msg, null];

/* Constantes del protocolo (deben coincidir con el firmware):
 * el nodo habla solo cuando detecta algo o cada 10 min (corazon).
 * El hub lo declara perdido tras 3 corazones sin respuesta (30 min). */
const HB = 600, PERDIDO = HB * 3;

const row = Array.isArray(msg.payload) ? msg.payload[0] : null;
if (!row) {
    msg.statusCode = 404;
    msg.payload = { error: 'Nodo no encontrado o sin permisos' };
    return msg;
}
const ms = (iso) => (iso ? Date.now() - new Date(iso).getTime() : null);const fmt = (s) => {
    if (s == null) return 'nunca';
    if (s < 0) s = 0;
    if (s < 90) return Math.round(s) + ' s';
    if (s < 5400) return Math.round(s / 60) + ' min';
    if (s < 172800) return (s / 3600).toFixed(1) + ' h';
    return Math.round(s / 86400) + ' dias';
};

const pruebas = [];
/* Ojo: null/1000 da 0 en JavaScript, y 0 pasa por "recien visto". Hay que
 * distinguir "nunca" de "hace un momento", si no un nodo que jamas hablo
 * sale como perfectamente activo. */
const eEv  = ms(row.ultimo_evento);
const eHub = ms(row.hub_last_seen);
const edadEv  = (eEv  == null) ? null : eEv  / 1000;
const edadHub = (eHub == null) ? null : eHub / 1000;

/* --- 1. Enlace con el hub --- */
const hubVivo = row.hub_status === 'active' && edadHub != null && edadHub < 600;
pruebas.push({
    clave: 'hub', etiqueta: 'Hub por el que habla',
    valor: (row.hub_name || '-') + ' (' + row.hub_serial + ')',
    estado: hubVivo ? 'ok' : 'mal',
    detalle: hubVivo ? ('en linea, visto ' + fmt(edadHub))
                     : ('sin senales ' + fmt(edadHub) + ' - sin el hub no hay nada que probar')
});

/* --- 2. Comunicacion ESP-NOW del nodo --- */
let estadoNodo, etiquetaNodo, detNodo, valorNodo;
if (edadEv == null)      { estadoNodo = 'mal';  etiquetaNodo = 'nunca ha hablado'; }
else if (edadEv < PERDIDO) { estadoNodo = 'ok'; etiquetaNodo = 'activo'; }
else if (edadEv < PERDIDO * 4) { estadoNodo = 'aviso'; etiquetaNodo = 'silencioso'; }
else { estadoNodo = 'mal'; etiquetaNodo = 'perdido'; }
detNodo = 'ultimo mensaje: ' + fmt(edadEv) + (row.ultimo_tipo ? ' (' + row.ultimo_tipo + ')' : '');
valorNodo = fmt(edadEv);

/* Un ping reciente vale mas que el historial: 'Probar ESP-NOW' interroga al
 * nodo en este momento y mide la respuesta. Si salio bien, el enlace esta vivo
 * aunque el nodo todavia no haya mandado su corazon de diez minutos. Caduca a
 * la hora para que la ficha no se quede colgada de una prueba antigua. */
const ping = (global.get('s360diag') || {})[String(row.mac_address || '').toLowerCase()];
const edadPing = (ping && ping.resuelto_en) ? ms(ping.resuelto_en) : null;
if (edadPing != null && edadPing >= 0 && edadPing < 3600000) {
    const ps = edadPing / 1000;
    const intentos = (ping.intentos != null ? ping.intentos : '?');
    if (ping.state === 'ok') {
        estadoNodo = 'ok'; etiquetaNodo = 'probado hace ' + fmt(ps);
        const rtt = (ping.rtt_ms != null ? ping.rtt_ms + ' ms' : 'sin medir');
        detNodo = 'el portal lo probo hace ' + fmt(ps) + ' y respondio en ' + rtt +
                  ' (' + intentos + ' intento' + (intentos === 1 ? '' : 's') + ')';
        if (edadEv == null) detNodo += ' - todavia no manda corazon';
        valorNodo = 'responde';
    } else {
        estadoNodo = 'mal'; etiquetaNodo = 'sin respuesta';
        const porQue = (ping.razon ? ping.razon : 'fallo');
        detNodo = 'ultimo ping hace ' + fmt(ps) + ': ' + porQue + ' (' + intentos + ' intentos)';
        valorNodo = 'no responde';
    }
}
pruebas.push({ clave: 'espnow', etiqueta: 'Habla por ESP-NOW',
               valor: valorNodo, estado: estadoNodo, detalle: detNodo });

/* --- 3. Batterie --- */
if (row.bateria == null) {
    pruebas.push({ clave: 'bateria', etiqueta: 'Bateria', valor: 'desconocida',
                   estado: 'neutro', detalle: 'el nodo nunca reporto bateria' });
} else {
    const b = Number(row.bateria);
    pruebas.push({ clave: 'bateria', etiqueta: 'Bateria', valor: b + ' %',
                   estado: b >= 40 ? 'ok' : (b >= 15 ? 'aviso' : 'mal'),
                   detalle: b < 15 ? 'nivel critico, recargala ya' :
                            (b < 40 ? 'por debajo del 40 %, conviene recargar' : 'nivel normal') });
}

/* --- 4. Lectura del sensor --- */
/* 255 y 254 no son distancias: son los codigos con los que el nodo avisa de que
 * no midio (DIST_SIN_ECO_CM y DIST_OUT_OF_RANGE_CM en el firmware). */
const SIN_ECO = 255, FUERA_RANGO = 254;
const ceros = Number(row.ceros_24h || 0), medidas = Number(row.medidas_24h || 0);
const sinEco = Number(row.sin_eco_24h || 0), fueraRango = Number(row.fuera_rango_24h || 0);
const ult = (row.distancia == null) ? null : Number(row.distancia);
const comoDist = v => (v === null ? '-'
                   : v === SIN_ECO ? 'sin eco'
                   : v === FUERA_RANGO ? 'fuera de rango'
                   : v + ' cm');

if (row.device_type === 'sensor_magnetic') {
    const estadoTxt = (ult === 1) ? 'Cerrado' : (ult === 0 ? 'Abierto' : 'sin datos');
    pruebas.push({ clave: 'sensor', etiqueta: 'Estado del sensor',
                   valor: estadoTxt,
                   estado: (ult == null) ? 'neutro' : 'ok',
                   detalle: (medidas + ceros) + ' reportes de estado en las ultimas 24 h' });
} else if (medidas === 0 && sinEco > 0 && sinEco >= fueraRango) {
    pruebas.push({ clave: 'sensor', etiqueta: 'Sensor de distancia',
                   valor: 'sin eco', estado: 'mal',
                   detalle: 'los ' + sinEco + ' mensajes de 24 h avisan de que no vuelve ningun pulso por ECHO. '
                   + 'El HC-SR04 se alimenta a 5 V y saca un ECHO de 5 V: hace falta un divisor a 3 V3 antes del GPIO3. '
                   + 'Revisa tambien TRIG y ECHO cruzados, el 5 V del modulo y que el sensor no este frito.' });
} else if (medidas === 0 && fueraRango > 0) {
    pruebas.push({ clave: 'sensor', etiqueta: 'Sensor de distancia',
                   valor: 'eco fuera de rango', estado: 'aviso',
                   detalle: 'el pulso de eco dura mas de lo que se puede medir (' + fueraRango
                   + ' mensajes): eco multiple, sensor mal orientado o montado sobre una superficie que reverbera.' });
} else if (medidas === 0 && ceros > 0) {
    pruebas.push({ clave: 'sensor', etiqueta: 'Sensor de distancia',
                   valor: 'sin lecturas', estado: 'mal',
                   detalle: 'los ' + ceros + ' mensajes de 24 h traen 0 cm, un valor que el firmware actual ya no manda: '
                   + 'este nodo sigue corriendo una version vieja y habria que actualizarlo.' });
} else if (medidas === 0) {
    pruebas.push({ clave: 'sensor', etiqueta: 'Sensor de distancia', valor: 'sin datos',
                   estado: 'neutro', detalle: 'no hay eventos en las ultimas 24 h' });
} else {
    pruebas.push({ clave: 'sensor', etiqueta: 'Sensor de distancia',
                   valor: comoDist(ult),
                   estado: (sinEco > 0 || fueraRango > 0 || ceros > 0) ? 'aviso' : 'ok',
                   detalle: medidas + ' lecturas utiles, ' + sinEco + ' sin eco, ' + fueraRango
                   + ' fuera de rango y ' + ceros + ' en cero (ultima 24 h)' });
}

/* --- 5. Umbral y actividad --- */
pruebas.push({ clave: 'actividad', etiqueta: 'Actividad ultima jornada',
               valor: row.eventos_24h + ' eventos',
               estado: Number(row.eventos_24h) > 0 ? 'ok' : 'aviso',
               detalle: row.device_type === 'sensor_magnetic'
                        ? 'este nodo no tiene parametros ajustables: solo reporta estado'
                        : 'umbral ajustado a ' + (row.distance_threshold != null
                        ? row.distance_threshold + ' cm' : 'sin definir') });

const peores = pruebas.map(p => p.estado);
const veredicto = peores.includes('mal') ? 'mal'
                : peores.includes('aviso') ? 'aviso'
                : peores.includes('neutro') ? 'neutro' : 'ok';

msg.statusCode = 200;
msg.payload = {
    success: true,
    node_id: row.id, node_mac: row.mac_address, node_name: row.name,
    estado_bd: row.status,
    ultimo_evento: row.ultimo_evento || null,
    ultimo_tipo: row.ultimo_tipo || null,
    secuencia: row.sequence_number || null,
    veredicto, pruebas,
    ahora: new Date().toISOString()
};
return msg;
